import numpy as np

def damping_type(a, b, c):
    """'under', 'critical' or 'over' for a y'' + b y' + c y = 0 (a, c > 0)."""
    if a == 0:
        raise ValueError("not second order")
    d = b * b - 4 * a * c
    if abs(d) <= 1e-9 * max(b * b, abs(4 * a * c), 1e-300):
        return "critical"
    return "under" if d < 0 else "over"

def steady_amplitude(w, b, w0):
    """Steady amplitude of y'' + b y' + w0^2 y = cos(w t)."""
    return float(1 / np.sqrt((w0 ** 2 - w ** 2) ** 2 + (b * w) ** 2))
